//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/ffi` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/ffi_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_ffi_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.

use super::{assert_format, run_case};

/// Replays php-src `001.phpt`.
#[test]
fn test_php_src_ffi_001() {
    let out = run_case(r#"<?php
echo 'The extension "FFI" is available';
"#, &[(r#"ffi.enable"#, r#"1"#)], &[]);
    assert_eq!(out, r#"The extension "FFI" is available"#);
}

