/// Replays php-src `005.phpt`.
#[test]
fn test_php_src_ffi_005() {
    let out = run_case(r#"<?php
$m = FFI::new("int[2][2]");
$v = FFI::new("int[2]");
$v[1] = 42;
$m[1] = $v;
var_dump($m);
"#, &[(r#"ffi.enable"#, r#"1"#)], &[]);
    assert_format(&out, r#"object(FFI\CData:int32_t[2][2])#%d (2) {
  [0]=>
  object(FFI\CData:int32_t[2])#%d (2) {
    [0]=>
    int(0)
    [1]=>
    int(0)
  }
  [1]=>
  object(FFI\CData:int32_t[2])#%d (2) {
    [0]=>
    int(0)
    [1]=>
    int(42)
  }
}"#);
}

