/// Replays php-src `008.phpt`.
#[test]
fn test_php_src_ffi_008() {
    let out = run_case(r#"<?php
$a = FFI::new("int[3]");
$a[1] = 10;
$a[2] = 20;
var_dump(count($a));
foreach ($a as $key => $val) {
    echo "$key => $val\n";
}

$a = FFI::new("struct {int x,y;}");
try {
    var_dump(count($a));
} catch (Throwable $e) {
    echo get_class($e) . ": " . $e->getMessage()."\n";
}

try {
    foreach ($a as $key => $val) {
        echo "$key => $val\n";
    }
} catch (Throwable $e) {
    echo get_class($e) . ": " . $e->getMessage()."\n";
}
"#, &[(r#"ffi.enable"#, r#"1"#)], &[]);
    assert_eq!(out, r#"int(3)
0 => 0
1 => 10
2 => 20
FFI\Exception: Attempt to count() on non C array
FFI\Exception: Attempt to iterate on non C array"#);
}

/// Replays php-src `009.phpt`.
#[test]
fn test_php_src_ffi_009() {
    let out = run_case(r#"<?php
$a = FFI::new("int[3]");
$a[1] = 10;
$a[2] = 20;
$b = FFI::new("int[4]");
var_dump(FFI::memcmp($b, $a, FFI::sizeof($a)));
FFI::memcpy($b, $a, FFI::sizeof($a));
var_dump($b);
var_dump(FFI::memcmp($b, $a, FFI::sizeof($a)));
FFI::memset($a, -1, FFI::sizeof($a));
var_dump($a);
"#, &[(r#"ffi.enable"#, r#"1"#)], &[]);
    assert_format(&out, r#"int(-1)
object(FFI\CData:int32_t[4])#%d (4) {
  [0]=>
  int(0)
  [1]=>
  int(10)
  [2]=>
  int(20)
  [3]=>
  int(0)
}
int(0)
object(FFI\CData:int32_t[3])#%d (3) {
  [0]=>
  int(-1)
  [1]=>
  int(-1)
  [2]=>
  int(-1)
}"#);
}

